guidance.correct_example:
import structlog
logger = structlog.get_logger()

def process(a_data: dict) -> Result[str]:
    logger.info('processing', keys=list(a_data.keys()))
    return Result.success('done')

guidance.incorrect_example:
def process(a_data: dict) -> Result[str]:
    print(f'Processing {a_data}')
    return Result.success('done')
